KG42.register("rules-2d81cbfafaf006568ecf2a51",{"id":"42-data_center_space_time_flexibility::v141-c-R011","paper":"42-data_center_space_time_flexibility","record":{"rule_id":"v141-c-R011","mechanism_id":"v141-a-M03","name":"Social-welfare clearing objective","process_stage":"clearing","market_meaning":"The requested hub-load quantity submitted by the flexible consumer bounds its total cleared load in the hub-based welfare formulation. Scope: The flexible consumer's total cleared load requested at its hub node. The hub-based welfare formulation minimizes supply and transmission costs minus the bid-valued total cleared hub load. Scope: Hub-based virtual-link clearing for the flexible consumer. Virtual shifts must be nonnegative, and their total cannot exceed the consumer's cleared hub load. Scope: Virtual-load disaggregation in the hub-based welfare formulation.","independence_rationale":"Relations governed by the approved function clearing.social_welfare under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","clearing.social_welfare"],"E":[{"edge_id":"v141-c-R011-E001","source":"bidding.demand","target":"clearing.social_welfare","type":"limits","constraint_ids":["v141-c-R011-C001"],"evidence_ids":["v141-b-g02-e019","v141-b-g02-e020"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Hub-based virtual-link clearing for the flexible consumer. | The flexible consumer's total cleared load requested at its hub node. | Virtual-load disaggregation in the hub-based welfare formulation.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e019","v141-b-g02-e020"]},"x":[{"variable_id":"v141-c-R011-X-d","symbol":"d","meaning":"Total cleared load of the flexible consumer at its hub node in the hub-based welfare formulation.","kind":"operational","domain":"0 \\le d \\le \\bar d","unit":null,"indices":[],"evidence_ids":["v141-b-g02-e019","v141-b-g02-e020"]},{"variable_id":"v141-c-R011-X-delta","symbol":"\\delta_{n_h,n}","meaning":"Load shifted from the hub node n_h to alternate node n via a virtual link.","kind":"operational","domain":"\\delta_{n_h,n}\\ge 0,\\; n\\in N_d\\setminus\\{n_h\\}","unit":null,"indices":["n_h","n"],"evidence_ids":["v141-b-g02-e019","v141-b-g02-e020"]},{"variable_id":"v141-c-R011-X-p","symbol":"p_i","meaning":"Cleared injection of supplier i in the welfare clearing formulation.","kind":"operational","domain":"p \\in C_p","unit":null,"indices":["i\\in S"],"evidence_ids":["v141-b-g02-e020"]},{"variable_id":"v141-c-R011-X-f","symbol":"f_k","meaning":"Cleared flow on directed transmission edge k in the welfare clearing formulation.","kind":"operational","domain":"\\mathbb{R}","unit":null,"indices":["k\\in K"],"evidence_ids":["v141-b-g02-e020"]}],"theta":[{"parameter_id":"v141-c-R011-T-bar-d","symbol":"\\bar d","meaning":"Requested load quantity submitted in the flexible consumer's hub bid.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e019","v141-b-g02-e020"]},{"parameter_id":"v141-c-R011-T-alpha-d","symbol":"\\alpha^d","meaning":"Bid price for the flexible consumer's requested hub load.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e019","v141-b-g02-e020"]},{"parameter_id":"v141-c-R011-T-alpha-p","symbol":"\\alpha^{p}_{i}","meaning":"Bid price of supplier i in the welfare objective.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i\\in S"],"evidence_ids":["v141-b-g02-e020"]},{"parameter_id":"v141-c-R011-T-alpha-f","symbol":"\\alpha^{f}_{k}","meaning":"Bid price of directed transmission edge k in the welfare objective.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["k\\in K"],"evidence_ids":["v141-b-g02-e020"]}],"phi":[{"constraint_id":"v141-c-R011-C001","kind":"mathematical","role":"core","statement":"The requested hub-load quantity submitted by the flexible consumer bounds its total cleared load in the hub-based welfare formulation. Scope: The flexible consumer's total cleared load requested at its hub node.","expression":"0 \\le d \\le \\bar d","formalization_origin":"source","template_id":null,"members":["bidding.demand","clearing.social_welfare"],"variable_refs":["v141-c-R011-X-d"],"parameter_refs":["v141-c-R011-T-bar-d"],"evidence_ids":["v141-b-g02-e019","v141-b-g02-e020"]},{"constraint_id":"v141-c-R011-C002","kind":"mathematical","role":"core","statement":"The hub-based welfare formulation minimizes supply and transmission costs minus the bid-valued total cleared hub load. Scope: Hub-based virtual-link clearing for the flexible consumer.","expression":"\\sum_{i\\in S}\\alpha^{p}_{i}p_i+\\sum_{k\\in K}\\alpha^{f}_{k}f_k-\\alpha^d d","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R011-X-d","v141-c-R011-X-p","v141-c-R011-X-f"],"parameter_refs":["v141-c-R011-T-alpha-p","v141-c-R011-T-alpha-f","v141-c-R011-T-alpha-d"],"evidence_ids":["v141-b-g02-e020"]},{"constraint_id":"v141-c-R011-C003","kind":"mathematical","role":"core","statement":"Virtual shifts must be nonnegative, and their total cannot exceed the consumer's cleared hub load. Scope: Virtual-load disaggregation in the hub-based welfare formulation.","expression":"\\delta_{n_h,n}\\ge 0,\\; n\\in N_d\\setminus\\{n_h\\};\\quad d-\\sum_{n\\in N_d}\\delta_{n_h,n}\\ge 0","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R011-X-d","v141-c-R011-X-delta"],"parameter_refs":[],"evidence_ids":["v141-b-g02-e020"]}],"pi":[{"evidence_id":"v141-b-g02-e019","location":{"location_id":"src-1c03246cb9-p06-c2r3__v141-a-M03-bidding","page":6,"printed_page":null,"section":"2.4 Basic formulation with virtual links","anchor_text":"2.4. Basic formulation with virtual links b) We have seen that there is a natural incentive for flex","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Suppose the flexible consumer submits a bid for requested load \\bar d at a hub (reference) node n_h\\in N with bid price \\alpha^d and offers at set of alternate nodes N_d\\subseteq N such that n_h\\in N_d. We use \\delta_{n_h,n}\\in R_+ to denote the amount of load that is shifted from the hub node n_h to the alternate node n\\in N_d; we refer to the load-shifting pathway as a virtual link."},{"evidence_id":"v141-b-g02-e020","location":{"location_id":"src-1c03246cb9-p06-c2r4__v141-a-M03-clearing","page":6,"printed_page":null,"section":"2.4 Basic formulation with virtual links","anchor_text":"∑ ∑ min 𝛼𝑝𝑖𝑝𝑖+ 𝛼𝑓𝑘𝑓𝑘−𝛼𝑑𝑑 (2.23a) b) 𝑑,𝑝,𝑓,𝜃,𝛿 𝑖∈ 𝑘∈ ∑ ∑ s.t. 𝑓𝑘+ 𝑝𝑖 𝑘∈rec𝑛 𝑖∈𝑛 a) 𝑛= 𝑛ℎ ⎧ 𝑑−∑ 𝑗∈","equation_id":"2.23","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"This leads to the following clearing formulation: min_{d,p,f,\\theta,\\delta}\\sum_{i\\in S}\\alpha^{p}_{i}p_i+\\sum_{k\\in K}\\alpha^{f}_{k}f_k-\\alpha^d d (2.23a) s.t. \\sum_{k\\in K^{rec}_n}f_k+\\sum_{i\\in S_n}p_i=\\sum_{k\\in K^{snd}_n}f_k+\\begin{cases}d-\\sum_{j\\in N_d}\\delta_{n_h,j}, & n=n_h\\\\ \\delta_{n_h,n}, & n\\in N_d\\setminus\\{n_h\\}\\\\ 0, & n\\in N\\setminus N_d\\end{cases} (\\pi_n) (2.23b); 0\\le d\\le\\bar d (2.23c); \\delta_{n_h,n}\\ge0, n\\in N_d\\setminus\\{n_h\\} (2.23d); d-\\sum_{n\\in N_d}\\delta_{n_h,n}\\ge0 (2.23e); f_{l^+}-f_{l^-}=B_l(\\theta_{snd(l)}-\\theta_{rec(l)}), l\\in L (2.23f); p\\in C_p, \\theta\\in C_\\theta (2.23g)."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M03-bidding","v141-a-M03-clearing","v141-a-M03-participation"],"extras":{"decision_anchor":"clearing.social_welfare","graph_fact_supports":[[{"evidence_id":"v141-b-g02-e019","quote":"the flexible consumer submits a bid for requested load \\bar d at a hub (reference) node n_h\\in N with bid price \\alpha^d"},{"evidence_id":"v141-b-g02-e020","quote":"0\\le d\\le\\bar d (2.23c)"}],[{"evidence_id":"v141-b-g02-e020","quote":"This leads to the following clearing formulation: min_{d,p,f,\\theta,\\delta}\\sum_{i\\in S}\\alpha^{p}_{i}p_i+\\sum_{k\\in K}\\alpha^{f}_{k}f_k-\\alpha^d d (2.23a)"}],[{"evidence_id":"v141-b-g02-e020","quote":"\\delta_{n_h,n}\\ge0, n\\in N_d\\setminus\\{n_h\\} (2.23d); d-\\sum_{n\\in N_d}\\delta_{n_h,n}\\ge0 (2.23e)"}]],"C2_formalization":{"graph_sha256":"7a3ab1f8d1697226206ec8b8ac4ee59c4e6dde920bd3faf56e05cc9db9316e07","applicability":"formalized","reason":"Formalizes the hub-load bound, welfare objective function, and virtual-shift feasibility constraints transcribed from (2.23a,c,d,e). Variables and objective coefficients are declared from the same source formula. B evidence is unreviewed; this is a provisional formalization and does not claim independent source verification. The printed summation in (2.23e) is preserved exactly even though (2.23d) defines nonnegativity only for n in N_d minus {n_h}.","bindings":[{"object_id":"v141-c-R011-X-d","node_ids":["clearing.social_welfare"],"edge_ids":["v141-c-R011-E001"],"rationale":"Cleared hub load d is a clearing variable in social_welfare; its upper bound is the requested bid quantity, represented by the demand-to-clearing limits edge."},{"object_id":"v141-c-R011-X-delta","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Virtual shifts are disaggregation variables local to the social-welfare clearing formulation; their total is bounded by d, but no separate graph edge exists for this relation."},{"object_id":"v141-c-R011-X-p","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Supplier injections p_i are clearing-side decision variables in the welfare objective located at clearing.social_welfare."},{"object_id":"v141-c-R011-X-f","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Directed-edge flows f_k are clearing-side decision variables in the welfare objective located at clearing.social_welfare."},{"object_id":"v141-c-R011-T-bar-d","node_ids":["bidding.demand"],"edge_ids":["v141-c-R011-E001"],"rationale":"Requested hub load is the bid quantity whose bound on d is represented by the demand-to-clearing limits edge E001."},{"object_id":"v141-c-R011-T-alpha-d","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"The hub bid price is submitted by the flexible consumer and enters the welfare objective, but it is not itself the bound represented by E001."},{"object_id":"v141-c-R011-T-alpha-p","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Supplier bid price is an objective coefficient in the welfare expression; no separate supply-bid node appears in this frozen rule."},{"object_id":"v141-c-R011-T-alpha-f","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Transmission bid price is an objective coefficient in the welfare expression; no separate transmission node appears in this frozen rule."},{"object_id":"v141-c-R011-C001","node_ids":["bidding.demand","clearing.social_welfare"],"edge_ids":["v141-c-R011-E001"],"rationale":"The inequality 0 \u003c= d \u003c= bar d expresses the demand-to-clearing limits relation: the requested hub load bounds the cleared hub load."},{"object_id":"v141-c-R011-C002","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"The objective function is the welfare objective located at clearing.social_welfare; supply and transmission terms are clearing-side variables and parameters within this rule."},{"object_id":"v141-c-R011-C003","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"The virtual-shift nonnegativity and total-shift bound are local disaggregation constraints in the social-welfare clearing formulation; no graph edge corresponds to them."}],"revision_requests":["Source (2.23e) sums delta over N_d while (2.23d) states nonnegativity only for n in N_d minus {n_h}; the formal expression preserves the printed summation, but the status of a hub-to-hub term delta_{n_h,n_h} remains unresolved."]},"C2_delivery":{"raw_sha256":"afdb79f3e9d24ac09d4919c0cd62b597a646ac2a7a71244b0ce9b8aa4f84b77a","delivery_payload_sha256":"375f9edca06ea94c61200b4fda71f4200c601790120ac4a60fce6f30f3fdf2fb","changes":[{"path":"theta.0.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.1.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.2.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.3.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."}],"scientific_fields_unchanged":true,"request_graph_sha256":"7a3ab1f8d1697226206ec8b8ac4ee59c4e6dde920bd3faf56e05cc9db9316e07","scientific_correctness_verified":false}},"quarantined_references":[]}});
